import {logo,godArt,bossArt,templeArt,icons} from './art.js';
import {stages,quests,stats,shiftDay,dayNow,weekStart,sharedStreak,bossState} from './game.js';
import {getSession,storeSession,authenticate,rpc,signout,recover} from './api.js';
const app=document.querySelector('#app'),modal=document.querySelector('#modal');let state,calendarMonth='',tab='home',demo=false,busy=false,authMode='login',chosenGod='zeus',timerEnd=0,timerHandle=0,notificationTimer=0,lastDay=dayNow();
const incomingInvite=location.hash.match(/^#join=([a-f0-9]{32})$/);if(incomingInvite){try{localStorage.setItem('olympus.invite',incomingInvite[1])}catch{}}
const read=(k,f)=>{try{return JSON.parse(localStorage.getItem(k))??f}catch{return f}};
let reduced=read('olympus.reduced',false);document.body.classList.toggle('reduced',reduced);
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true">${icons[k]}</svg>`;
const me=()=>state?.profiles?.find(p=>p.id===state.me);
const friend=()=>state?.profiles?.find(p=>p.id!==state.me);
const s=()=>stats(state.activities,state.me,state.today);
const coins=()=>Math.max(0,s().earned-state.purchases.reduce((a,p)=>a+p.cost,0));
const has=item=>state.purchases.some(p=>p.item===item);
const done=id=>state.activities.some(a=>a.user_id===state.me&&a.day===state.today&&a.kind==='quest'&&a.item===id);
const check=()=>state.activities.find(a=>a.user_id===state.me&&a.day===state.today&&a.kind==='checkin');
const godIcon=g=>({zeus:'ϟ',poseidon:'♆',hades:'♜'}[g]||'ϟ');
function toast(message){const el=document.querySelector('#toast');el.textContent=message;el.classList.add('show');clearTimeout(notificationTimer);notificationTimer=setTimeout(()=>el.classList.remove('show'),4000)}
function celebrate(){if(reduced||matchMedia('(prefers-reduced-motion: reduce)').matches)return;const el=document.querySelector('#confetti');el.innerHTML=Array.from({length:30},(_,i)=>`<i class="confetto" style="--x:${(Math.random()-.5)*550}px;--y:${Math.random()*350-180}px;--r:${Math.random()*700}deg;background:${['#e9c777','#9dbd86','#ebe3c9'][i%3]}"></i>`).join('');setTimeout(()=>el.innerHTML='',1500)}
function showModal(html){modal.innerHTML='<button class="close" data-action="close" aria-label="Close dialog">×</button>'+html;if(!modal.open)modal.showModal()}
function closeModal(){if(timerHandle){clearInterval(timerHandle);timerHandle=0}modal.close()}
function storeDemo(){localStorage.setItem('olympus.demo.v1',JSON.stringify(state))}
function demoSeed(){const today=dayNow(),activities=[];for(let i=1;i<=4;i++){for(const id of ['you','friend'])activities.push({user_id:id,day:shiftDay(today,-i),kind:'checkin',item:'',payload:{status:'success'}})}activities.push({user_id:'you',day:shiftDay(today,-1),kind:'quest',item:'walk',payload:{}});return{today,me:'you',profiles:[{id:'you',name:'Hero',god:'zeus'},{id:'friend',name:'Alex · demo',god:'poseidon'}],duo:{id:'demo',invite:'demo',rules:{goal:'Climb together',days:30,reward:'A victory dinner',definition:'Masturbation counts as a slip',revision:1}},activities,purchases:[],notes:[]}}
function setDemo(){demo=true;state=read('olympus.demo.v1',null)||demoSeed();state.today=dayNow();render()}
async function perform(op,p={},message='Saved'){if(busy)return;busy=true;document.querySelectorAll('[data-mutation]:not(:disabled)').forEach(b=>{b.dataset.pending='true';b.disabled=true});const previous=state?s().stage:0;try{if(demo){mutateDemo(op,p);storeDemo()}else state=await rpc(op,p);if(state.needs_setup){setup();return}closeModal();render();if(message)toast(message);if(op==='setup')presentInvite();if(op==='checkin')document.querySelector('.boss-art')?.classList.add('hit');if(['checkin','purchase','chest'].includes(op)){celebrate();if(s().stage>previous)showModal(`<div class="center"><div class="eyebrow">A new chapter begins</div>${godArt(me().god,s().stage)}<h2>${stages[s().stage].title}</h2><p>You reached ${s().current} days. This form is now in your trophy room.</p><button class="btn primary full" data-action="close">Continue the ascent →</button></div>`)}
}catch(e){toast(e.message)}finally{busy=false;document.querySelectorAll('[data-pending]').forEach(b=>{b.disabled=false;delete b.dataset.pending})}}
function mutateDemo(op,p){const today=state.today,id=state.me,add=(kind,item='',payload={})=>{let a=state.activities.find(x=>x.user_id===id&&x.day===today&&x.kind===kind&&x.item===item);if(a)a.payload=payload;else state.activities.push({user_id:id,day:today,kind,item,payload})};
if(op==='checkin')add('checkin','',{status:p.status});if(op==='quest')add('quest',p.item);if(op==='setup'){me().name=p.name;me().god=p.god}if(op==='purchase'){const cost={temple1:100,temple2:200,temple3:300,aura:120,banner:120}[p.item];if(has(p.item))throw Error('Already unlocked');if(coins()<cost)throw Error('Complete more quests to earn coins');state.purchases.push({item:p.item,cost})}if(op==='chest'){if(s().success<5)throw Error('Complete five successful days first');if(!has('chest-laurel'))state.purchases.push({item:'chest-laurel',cost:0})}if(op==='note'){state.notes=state.notes.filter(n=>n.day!==today);state.notes.push({day:today,body:p.body})}if(op==='support')add('support','',{message:p.item,duo:'demo'});if(op==='respond')add('quest','support');if(op==='rules')state.duo.rules={...p,revision:(state.duo.rules.revision||1)+1};if(op==='agree')add('agree',state.duo.id,{revision:state.duo.rules.revision});if(op==='join_duo'||op==='create_duo')throw Error('Sign in to create a real duo')}
function nav(){return ['home','adventure','profile'].map(k=>`<button class="navbtn ${tab===k?'active':''}" data-tab="${k}">${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}
function render(){if(!state)return auth();if(state.needs_setup)return setup();const m=me();document.documentElement.style.setProperty('--accent',m.god==='poseidon'?'#8acdc4':m.god==='hades'?'#c394da':'#e9c777');app.innerHTML=`${demo?'<div class="demo-tag">DEMO · sample duo · saved on this device only <button data-action="exitdemo">Sign in for real</button></div>':''}<div class="shell"><header class="header"><div class="brand" style="color:var(--gold)">${logo}<span>OLYMPUS</span></div><nav class="desktopnav" aria-label="Main navigation">${nav()}</nav><div class="header-right"><span class="tiny">YOUR TREASURY</span><span class="coin">◈ ${coins()}</span><button class="avatar-small" data-tab="profile" aria-label="Open profile">${esc(m.name[0]?.toUpperCase()||'H')}</button></div></header>${tab==='home'?home():tab==='adventure'?adventure():profile()}<p class="footerhint">One day at a time. A little stronger together. &nbsp;✧</p></div><nav class="bottomnav" aria-label="Main navigation">${['home','adventure','profile'].map(k=>`<button class="${tab===k?'active':''}" data-tab="${k}">${icon(k)}${k[0].toUpperCase()+k.slice(1)}</button>`).join('')}</nav>`}
function welcome(title,sub,eyebrow='YOUR DAILY ASCENT'){return `<div class="welcome"><div><div class="eyebrow">${eyebrow}</div><h1>${title}</h1><p>${sub}</p></div><div class="date">${new Date(state.today+'T12:00Z').toLocaleDateString('en-IN',{weekday:'long',day:'numeric',month:'long'})}</div></div>`}
function home(){const m=me(),a=s(),f=friend(),todayCheck=check(),stage=stages[a.stage],next=stages[a.stage+1];return `${welcome(`The ascent continues, ${esc(m.name)}.`,`Great things are built one ordinary day at a time.`)}${supportBanner()}${!state.duo?'<div class="banner"><div>Every god needs an ally.<p>Invite your friend to begin your shared adventure.</p></div><button class="btn" data-action="invite">Find your duo →</button></div>':''}<div class="grid"><section class="card hero"><div class="hero-top"><span class="eyebrow">${esc(m.god)}’S PATH</span><span class="pill">LEVEL ${a.level}</span></div><div class="hero-main"><div class="hero-copy"><span class="tiny">YOUR CURRENT FORM</span><h2>${stage.title}</h2><p>${next?`${Math.max(0,next.day-a.current)} more ${next.day-a.current===1?'day':'days'} to ${next.title}. Your next chapter awaits.`:'You have reached Olympus. Keep writing your legend.'}</p></div><div class="hero-art ${has('aura')?'owned-aura':''}">${godArt(m.god,a.stage)}</div></div><div class="hero-bottom"><span class="pill">✧ ${a.xp} XP</span><div class="xp"><div class="barlabel"><span>Level ${a.level}</span><span>${a.xp%250} / 250 XP</span></div><div class="bar"><span style="width:${a.xp%250/250*100}%"></span></div></div></div></section><div class="stack"><section class="card check-card"><div class="row"><h3 class="check-title">Make today count.</h3><span class="tiny"><span class="status-dot"></span>${todayCheck?'LOGGED':'DAY IS YOURS'}</span></div><p>${todayCheck?(todayCheck.payload.status==='success'?'Your check-in is saved. Enjoy the rest of your day.':'A fresh start is already yours. You’re still in this.'):'One small check-in. Another step toward Olympus.'}</p><button class="btn primary full" data-action="${todayCheck?'checkin':'success'}" data-mutation>${todayCheck?'✓ Today is logged · edit':'ϟ  Stayed on track'}</button><p class="checkhint">${todayCheck?'Your progress is synced'+(demo?' in demo mode':' privately'): '<button class="linkbtn" data-action="slip">Had a slip? Start fresh here.</button>'}</p></section><div class="streaks"><div class="streak"><strong>${a.current}</strong><span class="flame">♨</span><small>YOUR STREAK · DAYS</small></div><div class="streak"><strong>${sharedStreak(state.activities,state.profiles.map(p=>p.id),state.today)}</strong><span class="flame">⛓</span><small>TOGETHER · DAYS</small></div></div></div></div><div class="section-head"><h2>Better together.</h2><button class="linkbtn" data-action="invite">${f?'Your duo ↗':'Invite an ally ↗'}</button></div><section class="card duo-card">${playerCard(m,true)}<div class="chain">∞</div>${f?playerCard(f,false):'<div class="player right"><div><b>Your future ally</b><p>An adventure for two</p></div><div class="portrait">+</div></div>'}</section><div class="section-head"><h2>A little adventure, every day.</h2><button class="breathelink" data-action="distract"><span class="leaf">❋</span> Need a reset?</button></div><div class="lowergrid">${bossCard()}<section class="card"><div class="row"><h3>Side quests</h3><span class="tiny">OPTIONAL · +25 XP EACH</span></div>${quests.slice(0,3).map(questRow).join('')}</section></div>${a.current===0&&state.activities.some(x=>x.user_id===state.me&&x.kind==='checkin'&&x.payload.status==='slip')?'<div class="banner"><div>🔥 The Phoenix chapter<p>Three successful days unlock your comeback badge. Your earned rewards stay.</p></div><span class="pill">'+Math.min(a.current,3)+' / 3</span></div>':''}`}
function playerCard(p,isMe){const a=stats(state.activities,p.id,state.today),logged=state.activities.find(x=>x.user_id===p.id&&x.day===state.today&&x.kind==='checkin');const text=logged?(logged.payload.status==='success'?'✓ Checked in today':'Taking a fresh start'):'Today’s check-in awaits';return `<div class="player ${isMe?'':'right'}">${isMe?`<div class="portrait">${godIcon(p.god)}</div>`:''}<div><b>${esc(p.name)} ${isMe?'<span class="muted">· you</span>':''}</b><p>${text}</p><p style="color:var(--gold)">${a.current} day streak · ${stages[a.stage].title}</p></div>${!isMe?`<div class="portrait">${godIcon(p.god)}</div>`:''}</div>`}
function bossCard(){const b=bossState(state);return `<section class="card boss-card"><span class="eyebrow">WEEKLY CO-OP BOSS</span><div class="boss-art">${bossArt(b.index)}</div><div class="boss-copy"><h2>${b.names[b.index]}</h2><p>${b.damage>=b.max?'Victory is yours. Olympus remembers.':'Every check-in strikes. Together, you hit harder.'}</p><span class="pill">${b.comboDays?'⚡ '+b.comboDays+' DUO COMBO'+(b.comboDays>1?'S':''):'⚔ +75 DAMAGE / SUCCESS'}</span></div><div class="boss-health"><div class="barlabel"><span>${b.damage>=b.max?'DEFEATED':`${b.max-b.damage} / ${b.max} HP`}</span><span>${Math.round(b.damage/b.max*100)}% conquered</span></div><div class="bar"><span style="width:${100-b.damage/b.max*100}%"></span></div><div class="row" style="margin-top:12px"><span class="tiny">Both succeed: +50 combo damage</span><button class="linkbtn" data-action="boss">Battle details ↗</button></div></div></section>`}
function questRow(q){const d=done(q.id);return `<div class="questrow"><span class="questicon">${q.icon}</span><div class="questtext"><b>${q.name}</b><small>${d?'Completed today · nicely done':q.desc}</small></div><button class="questbtn ${d?'done':''}" data-action="quest" data-id="${q.id}" data-mutation ${d?'disabled':''} aria-label="${d?'Completed':'Complete'} ${q.name}">${d?'✓':'+'}</button></div>`}
function supportBanner(){const f=friend();if(!f)return '';const r=state.activities.find(a=>a.user_id===f.id&&a.kind==='support'&&a.day===state.today&&a.payload.duo===state.duo?.id);if(!r)return '';return `<div class="banner"><div>♡ ${esc(f.name)} needs backup.<p>${esc(r.payload.message)} · today</p></div><button class="btn" data-action="respond" data-mutation ${done('support')?'disabled':''}>${done('support')?'✓ Responded':'I’m here'}</button></div>`}
function adventure(){const a=s(),temple=has('temple3')?3:has('temple2')?2:has('temple1')?1:0;return `${welcome('Your legend, in the making.','The climb is yours. The rewards stay with you.','THE ROAD TO OLYMPUS')}<div class="split"><section class="card"><div class="row"><h2>Journey to Olympus</h2><span class="pill">${a.current} DAYS</span></div><p>Your active form follows your streak. Earned forms stay in your trophy room.</p><div class="map">${stages.map((st,i)=>`<div class="mapstop ${a.bestStage>=i?'unlocked':''} ${a.stage===i?'current':''}"><div class="mapnumber">${st.symbol}</div><div><h3>${st.title}</h3><p>${st.place}</p></div><span class="mapdays">${st.day===0?'START':`DAY ${st.day}`}</span></div>`).join('')}</div></section><div class="stack">${bossCard()}<section class="card center"><div class="eyebrow">YOUR LITTLE PIECE OF OLYMPUS</div><h2 style="margin-top:8px">The sanctuary</h2>${templeArt(temple)}<p>${['An empty clearing. A future temple.','A foundation built on small wins.','Your sanctuary is taking shape.','A temple worthy of your legend.'][temple]}</p>${temple<3?`<button class="btn primary full" data-action="purchase" data-item="temple${temple+1}" data-mutation>Build ${['foundation','columns','crown'][temple]} · ◈ ${[100,200,300][temple]}</button>`:'<span class="pill">✧ FULLY RESTORED</span>'}</section></div></div><div class="section-head"><h2>Make the journey yours.</h2><span class="tiny">EARNED, NEVER BOUGHT</span></div><div class="split"><section class="card"><h3>Daily side quests</h3><p>Choose what helps you. Complete these honestly, at your pace.</p>${quests.map(questRow).join('')}</section><section class="card"><h3>The treasury</h3><p>Use your coins for a little extra magic.</p><div class="shop" style="margin-top:18px">${[{id:'aura',icon:'✨',name:'Celestial aura',cost:120},{id:'banner',icon:'🏛️',name:'Olympus banner',cost:120},{id:'chest-laurel',icon:'🎁',name:'Milestone chest',cost:0}].map(x=>`<div class="shopitem"><div class="emoji">${x.icon}</div><b style="font-size:12px">${x.name}</b><p>${x.id==='chest-laurel'?'Five successful days → golden laurel':'Permanent cosmetic unlock'}</p><button class="btn ${has(x.id)?'subtle':''}" data-action="${x.id==='chest-laurel'?'chest':'purchase'}" data-item="${x.id}" data-mutation ${has(x.id)?'disabled':''}>${has(x.id)?'✓ Unlocked':x.cost?'◈ '+x.cost:'Open chest'}</button></div>`).join('')}<div class="shopitem"><div class="emoji">🤝</div><b style="font-size:12px">Gods of Olympus</b><p>Both reach a five-day streak.</p><span class="pill">${state.profiles.length===2&&state.profiles.every(p=>stats(state.activities,p.id,state.today).best>=5)?'UNLOCKED':'DUO REWARD'}</span></div></div></section></div>`}
function calendar(){const a=s(),month=calendarMonth||state.today.slice(0,7),first=month+'-01',start=new Date(first+'T12:00Z').getUTCDay(),count=new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();return `<div class="calendar">${['S','M','T','W','T','F','S'].map(x=>`<span class="calhead">${x}</span>`).join('')}${Array.from({length:start},()=>'<span class="calday empty"></span>').join('')}${Array.from({length:count},(_,i)=>{const d=month+'-'+String(i+1).padStart(2,'0'),c=a.checks.find(x=>x.day===d);return `<div class="calday ${c?.payload.status||''} ${d===state.today?'today':''}" aria-label="${d}: ${c?.payload.status||'not logged'}">${i+1}</div>`}).join('')}</div>`}
function trophies(){const a=s(),t=stages.filter(x=>x.day>0&&x.day<=a.best).map(x=>`${x.symbol} ${x.title}`);if(has('chest-laurel'))t.push('🌿 Golden laurel');if(has('aura'))t.push('✨ Celestial aura');if(has('banner'))t.push('🏛️ Olympus banner');if(bossState(state).damage>=1200)t.push('⚔ Weekly conqueror');const slips=state.activities.filter(x=>x.user_id===state.me&&x.kind==='checkin'&&x.payload.status==='slip').map(x=>x.day).sort();if(slips.some(d=>[1,2,3].every(n=>state.activities.some(x=>x.user_id===state.me&&x.kind==='checkin'&&x.day===shiftDay(d,n)&&x.payload.status==='success'))))t.push('🔥 Phoenix');return t.length?t.map(x=>`<span class="trophy">${x}</span>`).join(''):'<p>Your first trophy is waiting at day three. Small steps count.</p>'}
function profile(){const m=me(),a=s();return `${welcome('A story only you can write.','Look back, make it yours, and keep moving.','YOUR SANCTUARY')}<div class="split"><div class="stack"><section class="card"><div class="profile-hero">${godArt(m.god,a.bestStage)}<div><div class="eyebrow">${esc(m.god)}’S PATH</div><h2 style="font-size:35px;margin-top:8px">${esc(m.name)}</h2><p>Level ${a.level} · ${a.xp} XP</p><button class="linkbtn" data-action="editprofile" style="padding-left:0;color:var(--gold)">Edit name & god ↗</button></div></div>${has('banner')?'<div class="banner center">🏛️ &nbsp; CHILD OF OLYMPUS</div>':''}${has('aura')?'<p class="center" style="color:var(--gold)">✦ Celestial aura equipped ✦</p>':''}</section><div class="progress-grid"><div class="card stat"><strong>${a.best}</strong><p>BEST STREAK</p></div><div class="card stat"><strong>${a.rate}%</strong><p>LOGGED DAYS WON</p></div><div class="card stat"><strong>${a.success}</strong><p>SUCCESSFUL DAYS</p></div></div><section class="card"><div class="row"><h3>Your calendar</h3><span class="tiny">${new Date((calendarMonth||state.today.slice(0,7))+'-01T12:00Z').toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</span></div><div class="row"><button class="linkbtn" data-action="calprev" aria-label="Previous month">← Previous</button><button class="linkbtn" data-action="calnext" aria-label="Next month">Next →</button></div>${calendar()}<p class="tiny" style="margin-top:16px">● Green: on track &nbsp; ● Peach: fresh start &nbsp; ○ Gold: today</p><p class="tiny">Days reset at midnight India time (IST).</p></section><section class="card"><div class="row"><h3>A moment for yourself</h3><span class="pill">ONLY YOU</span></div><p>What helped today? Your friend cannot see these notes.</p><form id="noteform"><label class="field" for="note">Today’s reflection</label><textarea id="note" name="body" maxlength="2000" placeholder="A small win, a feeling, a thought…">${esc(state.notes.find(n=>n.day===state.today)?.body||'')}</textarea><button class="btn full" data-mutation>Save reflection</button></form>${state.notes.filter(n=>n.day!==state.today&&n.body).sort((a,b)=>b.day.localeCompare(a.day)).map(n=>`<details class="rule"><summary>${esc(n.day)}</summary><p style="white-space:pre-wrap">${esc(n.body)}</p></details>`).join('')}</section></div><div class="stack"><section class="card"><div class="row"><h3>This week’s friendly rivalry</h3><span class="pill">RESETS MONDAY</span></div><p>Score = successful days × 50 + quests × 25.</p>${[...state.profiles].sort((p,q)=>{const x=stats(state.activities,p.id,state.today),y=stats(state.activities,q.id,state.today);return(y.weeklySuccess*50+y.weeklyQuests*25)-(x.weeklySuccess*50+x.weeklyQuests*25)}).map((p,i)=>{const x=stats(state.activities,p.id,state.today);return `<div class="weekly-player"><div><b>${i===0?'♛':'♧'} ${esc(p.name)}</b><p>${x.weeklySuccess} successful days · ${x.weeklyQuests} quests</p></div><strong>${x.weeklySuccess*50+x.weeklyQuests*25}</strong></div>`}).join('')}<button class="btn full" data-action="recap">View weekly recap ↗</button></section><section class="card"><h3>The trophy room</h3><p>Your unlocked forms and cosmetics belong to you.</p><div class="trophies">${trophies()}</div></section><section class="card"><h3>Your pact</h3>${state.duo?`<div class="rule"><span>THE GOAL</span>${esc(state.duo.rules.goal)}</div><div class="rule"><span>WHAT COUNTS AS A SLIP</span>${esc(state.duo.rules.definition)}</div><div class="rule"><span>CHALLENGE LENGTH</span>${esc(state.duo.rules.days)} days</div><div class="rule"><span>YOUR REAL-WORLD REWARD</span>${esc(state.duo.rules.reward)}</div><p class="tiny" style="margin-top:12px">${state.profiles.filter(p=>state.activities.some(a=>a.user_id===p.id&&a.kind==='agree'&&a.item===state.duo.id&&a.payload.revision===state.duo.rules.revision)).length} / ${state.profiles.length} players have agreed to this revision.</p><div class="modal-actions"><button class="btn" data-action="rules">Edit pact</button><button class="btn primary" data-action="agree" data-mutation>I agree</button></div>`:'<p>Create a duo to agree on your challenge rules.</p><button class="btn full" data-action="invite">Invite your friend</button>'}</section><section class="card"><h3>Make yourself comfortable</h3><label class="reduced-label"><input type="checkbox" id="reduced" ${reduced?'checked':''}> Reduce animations</label><p class="tiny">iPhone tip: Safari → Share → Add to Home Screen.</p><button class="btn full" data-action="signout">${demo?'Leave demo':'Sign out'}</button></section></div></div>`}
function auth(){clearInterval(pollTimer);app.innerHTML=`<main class="auth"><section class="auth-art"><div class="brand" style="color:var(--gold)">${logo}<span>OLYMPUS</span></div>${godArt('zeus',2)}<div class="eyebrow">AN ADVENTURE FOR TWO</div><h1>Become your<br>own legend.</h1><p>A private challenge. A trusted friend.<br>A little stronger, one day at a time.</p><div class="trophies"><span class="trophy">ϟ Evolve into gods</span><span class="trophy">⚔ Defeat bosses together</span></div></section><section class="auth-panel"><div class="eyebrow">YOUR ASCENT STARTS HERE</div><h2 style="margin-top:9px">${authMode==='signup'?'Begin your story.':'Welcome back, hero.'}</h2><p>Private progress. Shared adventures.</p><div class="auth-tabs"><button data-authmode="login" class="${authMode==='login'?'active':''}">Sign in</button><button data-authmode="signup" class="${authMode==='signup'?'active':''}">Create account</button></div><form id="authform"><label class="field">Email<input name="email" type="email" autocomplete="email" inputmode="email" required placeholder="you@example.com"></label><label class="field">Password<input name="password" type="password" minlength="8" autocomplete="${authMode==='signup'?'new-password':'current-password'}" required placeholder="At least 8 characters"></label><button class="btn primary full" type="submit">${authMode==='signup'?'Begin the ascent':'Enter Olympus'} →</button><div id="autherror" class="auth-error" role="alert"></div></form><div class="row" style="margin-top:10px"><button class="linkbtn" data-action="forgot">Forgot password?</button><button class="linkbtn" style="color:var(--gold)" data-action="demo">Explore the demo ↗</button></div><p class="auth-note">Your check-ins are shared only with your invited ally.<br>Reflections stay private. No proof or judgement.</p></section></main>`}
function setup(){chosenGod=me()?.god||'zeus';showModal(`<div class="eyebrow">CHOOSE YOUR BEGINNING</div><h2>Every legend has a name.</h2><p>Pick your path. You can change it anytime.</p><form id="setupform"><label class="field">Your name<input name="name" maxlength="30" required value="${esc(me()?.name||'')}" placeholder="What should we call you?" autocomplete="nickname"></label>${godChoices()}<button class="btn primary full" data-mutation>Begin my ascent →</button></form>`)}
function godChoices(){return `<div class="godchoices">${[['zeus','ϟ','Thunder'],['poseidon','♆','Ocean'],['hades','♜','Underworld']].map(([g,i,n])=>`<button class="godchoice ${chosenGod===g?'selected':''}" type="button" data-god="${g}"><span>${i}</span>${g[0].toUpperCase()+g.slice(1)}<p class="tiny">${n}</p></button>`).join('')}</div>`}
function invite(){if(demo)return showModal('<h2>Your real adventure awaits.</h2><p>This duo is sample data. Sign in to invite your actual friend.</p><button class="btn primary full" data-action="exitdemo">Sign in →</button>');if(state.duo){const url=new URL(location.href);url.hash='join='+state.duo.invite;return showModal(`<div class="eyebrow">YOUR PRIVATE DUO</div><h2>${friend()?'Your ally is here.':'Greatness loves company.'}</h2><p>${friend()?'You’re teamed up with '+esc(friend().name)+'. Only two players can join a duo.':'Share this private invitation with your friend. The first person to join becomes your ally.'}</p><label class="field">Invitation link<input id="invitelink" readonly value="${esc(url.href)}"></label><button class="btn primary full" data-action="share">Share invite ↗</button><p class="tiny" style="margin-top:12px">Anyone with this link can claim the empty place. Keep it between you two.</p>`)}showModal(`<h2>Find your ally.</h2><p>Create a private duo, or join your friend’s invitation.</p><button class="btn primary full" data-action="create_duo" data-mutation>Create our duo →</button><form id="joinform"><label class="field">Have an invite? Paste link or code<input name="code" required placeholder="Your friend’s invitation"></label><button class="btn full" data-mutation>Join my friend</button></form>`)}
function checkinDialog(){showModal(`<div class="eyebrow">YOUR DAY, HONESTLY</div><h2>How did today go?</h2><p>You can correct today’s check-in. A slip starts a fresh streak; past XP and unlocked rewards stay.</p><button class="btn primary full" data-action="success" data-mutation>ϟ Stayed on track</button><button class="btn full" data-action="slip">Had a slip · start fresh</button>`)}
function slipDialog(){showModal(`<div class="eyebrow">A NEW CHAPTER</div><h2>You’re still in this.</h2><p>Log today honestly and keep going. Your friend will see “Taking a fresh start.” No details are shared.</p><button class="btn primary full" data-action="confirm_slip" data-mutation>Log a slip & keep going</button><button class="btn subtle full" data-action="close">Go back</button>`)}
function distract(){timerEnd=read('olympus.timer',0);showModal(`<div class="eyebrow center">TAKE A LITTLE SPACE</div><h2 class="center">Let the moment pass.</h2><p class="center">Step away from your phone. Walk, stretch, or breathe slowly. You only need to do the next ten minutes.</p><div class="orb"></div><div class="timer" id="timer">10:00</div><button class="btn primary full" data-action="starttimer" id="timerbutton">${timerEnd>Date.now()?'Timer is running':'Start 10-minute reset'}</button><div class="modal-actions"><button class="btn" data-action="support">♡ Ask my ally</button><button class="btn" data-action="close">Back to my day</button></div><p class="tiny center" style="margin-top:18px">Timer progress survives a closed tab. Return here to finish.</p>`);if(timerEnd)tickTimer()}
function tickTimer(){if(timerHandle)clearInterval(timerHandle);const tick=()=>{const el=document.querySelector('#timer');if(!el)return;const left=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));el.textContent=`${String(Math.floor(left/60)).padStart(2,'0')}:${String(left%60).padStart(2,'0')}`;const b=document.querySelector('#timerbutton');if(left===0){clearInterval(timerHandle);timerHandle=0;b.textContent=done('breathe')?'✓ Reset completed':'Claim your calm · +25 XP';b.dataset.action='finishtimer';b.disabled=done('breathe')}else{b.textContent='Your moment of calm is running';b.disabled=true}};tick();timerHandle=setInterval(tick,1000)}
function support(){showModal(`<div class="eyebrow">YOU’VE GOT AN ALLY</div><h2>A little backup?</h2><p>Your friend will see this request when they open OLYMPUS. This does not send a phone notification.</p>${['Call me','Let’s walk','Let’s play'].map(t=>`<button class="btn full" data-action="sendsupport" data-message="${esc(t)}" data-mutation>${t} →</button>`).join('')}`)}
function rules(){const r=state.duo.rules;showModal(`<h2>Your pact.</h2><p>Changes need both players’ agreement. Keep the goal realistic and the reward fun.</p><form id="rulesform"><label class="field">Goal<input name="goal" required maxlength="100" value="${esc(r.goal)}"></label><label class="field">What counts as a slip<input name="definition" required maxlength="200" value="${esc(r.definition)}"></label><label class="field">Duration in days<input name="days" type="number" min="7" max="365" required value="${r.days}"></label><label class="field">Real-world reward<input name="reward" required maxlength="100" value="${esc(r.reward)}"></label><button class="btn primary full" data-mutation>Save pact for agreement</button></form>`)}
let pollTimer;
function presentInvite(){let code=location.hash.match(/^#join=([a-f0-9]{32})$/)?.[1];try{code=code||localStorage.getItem('olympus.invite')}catch{}if(code&&/^[a-f0-9]{32}$/.test(code)&&!state.duo){showModal(`<h2>Your ally is waiting.</h2><p>Join the private duo from your invitation?</p><button class="btn primary full" data-action="joininvite" data-code="${code}" data-mutation>Join this duo →</button>`)}}
async function load(){try{state=await rpc('state');if(state.needs_setup){auth();setup()}else{render();presentInvite()}startPolling()}catch(e){auth();toast(e.message)}}
function startPolling(){clearInterval(pollTimer);pollTimer=setInterval(async()=>{if(demo||!getSession()||busy||document.hidden||modal.open)return;try{const next=await rpc('state');if(!next.needs_setup){state=next;render()}}catch{}},30000)}
document.addEventListener('visibilitychange',async()=>{if(!document.hidden&&getSession()&&!demo&&!busy&&!modal.open){try{state=await rpc('state');render()}catch(e){toast(e.message)}}});
setInterval(()=>{const d=dayNow();if(state&&d!==lastDay){lastDay=d;if(demo){state.today=d;render()}else if(getSession())load()}},30000);
app.addEventListener('change',e=>{if(e.target.id==='reduced'){reduced=e.target.checked;localStorage.setItem('olympus.reduced',JSON.stringify(reduced));document.body.classList.toggle('reduced',reduced)}});
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.tab){tab=b.dataset.tab;render();window.scrollTo({top:0,behavior:'instant'});return}if(b.dataset.authmode){authMode=b.dataset.authmode;auth();return}if(b.dataset.god){chosenGod=b.dataset.god;document.querySelectorAll('[data-god]').forEach(x=>x.classList.toggle('selected',x.dataset.god===chosenGod));return}const action=b.dataset.action;if(!action)return;
if(action==='calprev'||action==='calnext'){let d=new Date((calendarMonth||state.today.slice(0,7))+'-01T12:00Z');d.setUTCMonth(d.getUTCMonth()+(action==='calprev'?-1:1));calendarMonth=d.toISOString().slice(0,7);render();return}if(action==='close')return closeModal();if(action==='demo')return setDemo();if(action==='exitdemo'){demo=false;state=null;closeModal();if(getSession())load();else auth();return}if(action==='signout'){await signout();demo=false;state=null;auth();return}if(action==='success')return perform('checkin',{status:'success'},check()?'Check-in updated. Your progress is saved.':'Today is yours. +50 XP · +20 coins');if(action==='confirm_slip')return perform('checkin',{status:'slip'},'Fresh start logged. Your journey continues.');if(action==='slip')return slipDialog();if(action==='checkin')return checkinDialog();if(action==='invite')return invite();if(action==='create_duo'){await perform('create_duo',{},'Your duo is ready');if(state.duo)invite();return}if(action==='joininvite'){await perform('join_duo',{code:b.dataset.code},'Your adventure together begins');if(state.duo){localStorage.removeItem('olympus.invite');history.replaceState(null,'',location.pathname+location.search);}return}if(action==='quest'){const q=quests.find(q=>q.id===b.dataset.id);if(q.id==='breathe')return distract();showModal(`<div class="eyebrow">OPTIONAL SIDE QUEST</div><h2>${q.name}</h2><p>${q.desc}</p><p>Mark this complete once you’ve done it. Each quest rewards you once per day.</p><button class="btn primary full" data-action="confirmquest" data-id="${q.id}" data-mutation>I did it · +25 XP</button>`);return}if(action==='confirmquest')return perform('quest',{item:b.dataset.id},'Quest complete. +25 XP · +10 coins');if(action==='purchase'){const item=b.dataset.item;if(has(item))return;return perform('purchase',{item},'Unlocked. This one is yours to keep.')}if(action==='chest')return perform('chest',{},'Chest opened: golden laurel unlocked!');if(action==='distract')return distract();if(action==='starttimer'){timerEnd=Date.now()+600000;localStorage.setItem('olympus.timer',String(timerEnd));return tickTimer()}if(action==='finishtimer'){if(timerEnd&&Date.now()>=timerEnd){await perform('quest',{item:'breathe'},'You made space. +25 XP');localStorage.removeItem('olympus.timer');timerEnd=0}return}if(action==='support')return support();if(action==='sendsupport')return perform('support',{item:b.dataset.message},'Request shared with your ally in OLYMPUS');if(action==='respond')return perform('respond',{},'Support acknowledged. Reach out to your friend!');if(action==='rules')return rules();if(action==='agree')return perform('agree',{},'Your agreement is saved');if(action==='editprofile'){chosenGod=me().god;return showModal(`<h2>Make it yours.</h2><form id="setupform"><label class="field">Your name<input name="name" value="${esc(me().name)}" required maxlength="30"></label>${godChoices()}<button class="btn primary full" data-mutation>Save my path</button></form>`)}if(action==='boss'){const bs=bossState(state);return showModal(`<div class="eyebrow">THE WEEKLY RAID</div><h2>${bs.names[bs.index]}</h2><div class="boss-preview">${bossArt(bs.index)}</div><p>Success: 75 damage. Quest: 15 damage. Both allies succeed on the same day: 50 extra damage.</p><div class="rule"><span>THIS WEEK</span>${bs.damage} / ${bs.max} damage · ${bs.comboDays} duo combos</div><p>Resets each Monday at midnight IST. The weekly enemy changes automatically.</p><button class="btn primary full" data-action="close">Back to the ascent</button>`)}if(action==='recap'){const a=s(),bs=bossState(state);return showModal(`<div class="eyebrow">YOUR WEEK SO FAR</div><h2>A little stronger.</h2><div class="rule"><span>SUCCESSFUL DAYS</span>${a.weeklySuccess}</div><div class="rule"><span>QUESTS COMPLETED</span>${a.weeklyQuests}</div><div class="rule"><span>DUO BOSS DAMAGE</span>${bs.damage} / ${bs.max}</div><div class="rule"><span>YOUR BEST STREAK</span>${a.best} days</div><p>Every honest check-in is a step forward.</p><button class="btn primary full" data-action="close">Keep going →</button>`)}if(action==='share'){const url=document.querySelector('#invitelink').value;try{if(navigator.share)await navigator.share({title:'Join my OLYMPUS duo',text:'Our climb starts here.',url});else{await navigator.clipboard.writeText(url);toast('Invitation copied')}}catch(e){if(e.name!=='AbortError'){document.querySelector('#invitelink').select();toast('Select and copy the invitation above')}}return}if(action==='forgot')showModal('<h2>Find your way back.</h2><p>Enter your account email to request a password reset.</p><form id="recoverform"><label class="field">Email<input name="email" type="email" required autocomplete="email"></label><button class="btn primary full">Send reset email</button></form>')});
document.addEventListener('submit',async e=>{const form=e.target;if(!['authform','setupform','noteform','joinform','rulesform','recoverform'].includes(form.id))return;e.preventDefault();const p=Object.fromEntries(new FormData(form));if(form.id==='authform'){const b=form.querySelector('button');b.disabled=true;b.textContent='Opening the gates…';try{const data=await authenticate(p.email,p.password,authMode==='signup');if(data.access_token)await load();else document.querySelector('#autherror').textContent='Check your email to confirm your account, then return here to sign in.'}catch(err){document.querySelector('#autherror').textContent=err.message}finally{b.disabled=false;b.textContent=authMode==='signup'?'Begin the ascent →':'Enter Olympus →'}return}if(form.id==='recoverform'){try{await recover(p.email);toast('If an account exists, a reset email is on its way.');closeModal()}catch(err){toast(err.message)}return}if(form.id==='setupform'){await perform('setup',{name:p.name,god:chosenGod},'Your path is set');return}if(form.id==='noteform')return perform('note',p,'Reflection saved. Only you can see it.');if(form.id==='joinform'){let code=p.code.trim();const match=code.match(/join=([a-f0-9]{32})/);if(match)code=match[1];return perform('join_duo',{code},'Your adventure together begins')}if(form.id==='rulesform')return perform('rules',{...p,days:Number(p.days)},'Pact updated. Both players can now agree.')});
// Email recovery and verification redirects are handled without leaking tokens to history.
const hash=new URLSearchParams(location.hash.slice(1));if(hash.has('access_token'))history.replaceState(null,'',location.pathname+location.search);if(hash.get('access_token')&&hash.get('refresh_token')&&hash.get('type')!=='recovery'){storeSession({access_token:hash.get('access_token'),refresh_token:hash.get('refresh_token'),expires_at:Date.now()+Number(hash.get('expires_in')||3600)*1000})}if(hash.get('type')==='recovery'&&hash.get('access_token')){showModal('<h2>Reset your password.</h2><form id="resetform"><label class="field">New password<input name="password" type="password" minlength="8" required autocomplete="new-password"></label><button class="btn primary full">Update password</button><p id="reseterror" class="auth-error"></p></form>');document.querySelector('#resetform').onsubmit=async e=>{e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const r=await fetch('https://viiapqmlvebglaugrtzj.supabase.co/auth/v1/user',{method:'PUT',headers:{apikey:'sb_publishable_6gjK6RNj9hVlcOkXOPU5qg_nfz_McTH',Authorization:'Bearer '+hash.get('access_token'),'Content-Type':'application/json'},body:JSON.stringify({password:new FormData(e.target).get('password')})});const data=await r.json();if(!r.ok)throw Error(data.msg||data.message||'Could not reset password');history.replaceState(null,'',location.pathname);closeModal();toast('Password updated. Sign in with your new password.')}catch(err){document.querySelector('#reseterror').textContent=err.message}finally{b.disabled=false}}}
auth();if(getSession()&&hash.get('type')!=='recovery')load();
if('serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
